#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stddef.h>

#ifdef __x86_64__
#include <immintrin.h>
#endif

typedef struct {
    char* key;
    int32_t id;
} vocab_entry;

typedef struct {
    vocab_entry* entries;
    size_t cap;
    size_t len;
} vocab_table;

static uint64_t fnv1a64(const char* s, size_t n) {
    uint64_t h = 14695981039346656037ULL;
    for (size_t i = 0; i < n; i++) {
        h ^= (uint64_t)(unsigned char)s[i];
        h *= 1099511628211ULL;
    }
    return h;
}

static void vocab_init(vocab_table* t, size_t cap) {
    if (cap == 0 || (cap & (cap - 1)) != 0) {
        size_t p = 16;
        while (p < cap) p <<= 1;
        cap = p;
    }
    t->cap = cap;
    t->len = 0;
    t->entries = (vocab_entry*)calloc(cap, sizeof(vocab_entry));
    if (!t->entries) {
        t->cap = 0;
    }
}

static void vocab_free(vocab_table* t) {
    if (!t) return;
    for (size_t i = 0; i < t->cap; i++) {
        free(t->entries[i].key);
    }
    free(t->entries);
    t->entries = NULL;
    t->cap = 0;
    t->len = 0;
}

static int vocab_put(vocab_table* t, const char* key, int32_t id) {
    if (!t || !t->entries || !key) return 0;
    if (t->len * 10 >= t->cap * 7) return 0;

    const size_t n = strlen(key);
    uint64_t h = fnv1a64(key, n);
    size_t idx = (size_t)(h % t->cap);
    size_t probe = 0;

    while (probe < t->cap) {
        if (!t->entries[idx].key) {
            char* dup = strdup(key);
            if (!dup) return 0;
            t->entries[idx].key = dup;
            t->entries[idx].id = id;
            t->len++;
            return 1;
        }
        if (strcmp(t->entries[idx].key, key) == 0) {
            t->entries[idx].id = id;
            return 1;
        }
        idx = (idx + 1) % t->cap;
        probe++;
    }
    return 0;
}

static int vocab_get(const vocab_table* t, const char* key, int32_t* out_id) {
    if (!t || !t->entries || !key || !out_id) return 0;

    const size_t n = strlen(key);
    uint64_t h = fnv1a64(key, n);
    size_t idx = (size_t)(h % t->cap);
    size_t probe = 0;

    while (probe < t->cap) {
        if (!t->entries[idx].key) return 0;
        if (strcmp(t->entries[idx].key, key) == 0) {
            *out_id = t->entries[idx].id;
            return 1;
        }
        idx = (idx + 1) % t->cap;
        probe++;
    }
    return 0;
}

typedef struct {
    vocab_table vocab;
    int32_t unk_id;
    int32_t cls_id;
    int32_t sep_id;
    int32_t pad_id;
    int32_t mask_id;
} tokenizer_t;

static size_t next_pow2(size_t x) {
    if (x == 0) return 1;
    if (x > (SIZE_MAX >> 1)) return SIZE_MAX;
    size_t p = 1;
    while (p < x) p <<= 1;
    return p;
}

tokenizer_t* tokenizer_load(const char* vocab_path) {
    if (!vocab_path) return NULL;

    FILE* f = fopen(vocab_path, "rb");
    if (!f) return NULL;

    size_t lines = 0;
    char buf[8192];
    while (fgets(buf, sizeof(buf), f)) {
        lines++;
    }

    if (fseek(f, 0, SEEK_SET) != 0) {
        fclose(f);
        return NULL;
    }

    tokenizer_t* tok = (tokenizer_t*)calloc(1, sizeof(tokenizer_t));
    if (!tok) {
        fclose(f);
        return NULL;
    }

    size_t cap = next_pow2(lines * 2 + 64);
    vocab_init(&tok->vocab, cap);
    if (!tok->vocab.entries) {
        free(tok);
        fclose(f);
        return NULL;
    }

    size_t id = 0;
    while (fgets(buf, sizeof(buf), f)) {
        size_t n = strlen(buf);
        while (n > 0 && (buf[n-1] == '\n' || buf[n-1] == '\r')) {
            buf[--n] = '\0';
        }
        if (n == 0) continue;
        if (id > INT32_MAX) break;
        vocab_put(&tok->vocab, buf, (int32_t)id);
        id++;
    }

    fclose(f);

    tok->unk_id = 100;
    tok->cls_id = 101;
    tok->sep_id = 102;
    tok->pad_id = 0;
    tok->mask_id = 103;

    int32_t tmp;
    if (vocab_get(&tok->vocab, "[UNK]", &tmp)) tok->unk_id = tmp;
    if (vocab_get(&tok->vocab, "[CLS]", &tmp)) tok->cls_id = tmp;
    if (vocab_get(&tok->vocab, "[SEP]", &tmp)) tok->sep_id = tmp;
    if (vocab_get(&tok->vocab, "[PAD]", &tmp)) tok->pad_id = tmp;
    if (vocab_get(&tok->vocab, "[MASK]", &tmp)) tok->mask_id = tmp;

    return tok;
}

void tokenizer_free(tokenizer_t* tok) {
    if (!tok) return;
    vocab_free(&tok->vocab);
    free(tok);
}

static int is_whitespace(char c) {
    return c == ' ' || c == '\n' || c == '\t' || c == '\r' || c == '\f' || c == '\v';
}

static size_t split_words(const char* s, size_t n, size_t* out_starts, size_t* out_lens, size_t max_words) {
    if (!s || !out_starts || !out_lens || max_words == 0) return 0;

    size_t w = 0;
    size_t i = 0;

    while (i < n && w < max_words) {
        while (i < n && is_whitespace(s[i])) i++;
        if (i >= n) break;

        size_t st = i;
        while (i < n && !is_whitespace(s[i])) i++;

        out_starts[w] = st;
        out_lens[w] = i - st;
        w++;
    }

    return w;
}

static size_t tokenize_word(const tokenizer_t* tok, const char* word, size_t wlen, int32_t* out_ids, size_t max_ids) {
    if (!tok || !word || wlen == 0 || !out_ids || max_ids == 0) return 0;

    char tmp[1024];
    size_t produced = 0;
    size_t pos = 0;

    if (wlen >= sizeof(tmp)) return 0;

    while (pos < wlen && produced < max_ids) {
        size_t end = wlen;
        int32_t found_id = -1;
        size_t found_len = 0;

        while (end > pos) {
            size_t seg_len = end - pos;
            if (seg_len >= sizeof(tmp) - 3) {
                end--;
                continue;
            }

            if (pos == 0) {
                memcpy(tmp, word + pos, seg_len);
                tmp[seg_len] = '\0';
            } else {
                tmp[0] = '#';
                tmp[1] = '#';
                memcpy(tmp + 2, word + pos, seg_len);
                tmp[2 + seg_len] = '\0';
            }

            int32_t id;
            if (vocab_get(&tok->vocab, tmp, &id)) {
                found_id = id;
                found_len = seg_len;
                break;
            }

            end--;
        }

        if (found_id < 0) {
            out_ids[produced++] = tok->unk_id;
            break;
        }

        out_ids[produced++] = found_id;
        pos += found_len;
    }

    return produced;
}

size_t tokenizer_encode(const tokenizer_t* tok, const char* text, int32_t* out_ids, size_t max_ids) {
    if (!tok || !text || !out_ids || max_ids == 0) return 0;

    const size_t n = strlen(text);
    size_t starts[8192];
    size_t lens[8192];
    const size_t words = split_words(text, n, starts, lens, 8192);

    size_t produced = 0;
    if (produced >= max_ids) return produced;
    out_ids[produced++] = tok->cls_id;

    for (size_t i = 0; i < words && produced < max_ids; i++) {
        size_t wp = tokenize_word(tok, text + starts[i], lens[i], out_ids + produced, max_ids - produced);
        produced += wp;
        if (produced >= max_ids) break;
    }

    if (produced < max_ids) {
        out_ids[produced++] = tok->sep_id;
    }

    return produced;
}
