typedef struct {
    const char* html;
    char* cleaned;
    int32_t* token_ids;
    size_t token_count;
} batch_item_t;

typedef struct {
    const batch_item_t* items;
    size_t n;
    size_t idx;
    pthread_mutex_t mu;
    tokenizer_t* tok;
} work_queue_t;

static void* worker(void* arg) {
    work_queue_t* q = (work_queue_t*)arg;

    for (;;) {
        pthread_mutex_lock(&q->mu);
        size_t i = q->idx++;
        pthread_mutex_unlock(&q->mu);

        if (i >= q->n) break;

        batch_item_t* it = (batch_item_t*)&q->items[i];

        clean_result_t cr = html_clean(it->html);
        char* norm = normalize_nfkc_lower(cr.text);
        html_clean_free(cr);

        it->cleaned = norm ? norm : strdup("");
        if (!it->cleaned) it->cleaned = strdup("");

        it->token_ids = (int32_t*)malloc(sizeof(int32_t) * 8192);
        if (it->token_ids) {
            it->token_count = tokenizer_encode(q->tok, it->cleaned, it->token_ids, 8192);
        } else {
            it->token_count = 0;
        }
    }

    return NULL;
}

int batch_process_html(const char** html_docs, size_t n_docs, const char* vocab_path, batch_item_t** out_items) {
    if (!html_docs || n_docs == 0 || !vocab_path || !out_items) return -1;

    tokenizer_t* tok = tokenizer_load(vocab_path);
    if (!tok) return -2;

    batch_item_t* items = (batch_item_t*)calloc(n_docs, sizeof(batch_item_t));
    if (!items) {
        tokenizer_free(tok);
        return -3;
    }

    for (size_t i = 0; i < n_docs; i++) {
        items[i].html = html_docs[i];
        items[i].cleaned = NULL;
        items[i].token_ids = NULL;
        items[i].token_count = 0;
    }

    work_queue_t q;
    q.items = items;
    q.n = n_docs;
    q.idx = 0;
    q.tok = tok;

    if (pthread_mutex_init(&q.mu, NULL) != 0) {
        free(items);
        tokenizer_free(tok);
        return -4;
    }

    size_t num_threads = 8;
    pthread_t threads[8];

    for (size_t i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, worker, &q) != 0) {
            for (size_t j = 0; j < i; j++) {
                pthread_join(threads[j], NULL);
            }
            pthread_mutex_destroy(&q.mu);
            for (size_t k = 0; k < n_docs; k++) {
                free(items[k].cleaned);
                free(items[k].token_ids);
            }
            free(items);
            tokenizer_free(tok);
            return -5;
        }
    }

    for (size_t i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&q.mu);
    tokenizer_free(tok);

    *out_items = items;
    return 0;
}
