#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unicode/unorm2.h>
#include <unicode/ustring.h>
#include <unicode/ucasemap.h>

char* normalize_nfkc_lower(const char* utf8) {
    if (!utf8) return NULL;

    UErrorCode status = U_ZERO_ERROR;
    const UNormalizer2* norm = unorm2_getNFKCInstance(&status);
    if (U_FAILURE(status)) return NULL;

    int32_t src_len = (int32_t)strlen(utf8);
    if (src_len < 0 || (size_t)src_len > INT32_MAX) return NULL;

    int32_t u16_cap = src_len * 2 + 32;
    UChar* u16 = (UChar*)malloc((size_t)u16_cap * sizeof(UChar));
    if (!u16) return NULL;

    int32_t u16_len = 0;
    u_strFromUTF8(u16, u16_cap, &u16_len, utf8, src_len, &status);

    if (status == U_BUFFER_OVERFLOW_ERROR) {
        status = U_ZERO_ERROR;
        u16_cap = u16_len + 16;
        UChar* temp = (UChar*)realloc(u16, (size_t)u16_cap * sizeof(UChar));
        if (!temp) {
            free(u16);
            return NULL;
        }
        u16 = temp;
        u_strFromUTF8(u16, u16_cap, &u16_len, utf8, src_len, &status);
    }

    if (U_FAILURE(status)) {
        free(u16);
        return NULL;
    }

    int32_t norm_cap = u16_len * 2 + 32;
    UChar* norm_buf = (UChar*)malloc((size_t)norm_cap * sizeof(UChar));
    if (!norm_buf) {
        free(u16);
        return NULL;
    }

    int32_t norm_len = unorm2_normalize(norm, u16, u16_len, norm_buf, norm_cap, &status);

    if (status == U_BUFFER_OVERFLOW_ERROR) {
        status = U_ZERO_ERROR;
        norm_cap = norm_len + 16;
        UChar* temp = (UChar*)realloc(norm_buf, (size_t)norm_cap * sizeof(UChar));
        if (!temp) {
            free(norm_buf);
            free(u16);
            return NULL;
        }
        norm_buf = temp;
        norm_len = unorm2_normalize(norm, u16, u16_len, norm_buf, norm_cap, &status);
    }

    free(u16);

    if (U_FAILURE(status)) {
        free(norm_buf);
        return NULL;
    }

    UCaseMap* csm = ucasemap_open("", 0, &status);
    if (U_FAILURE(status)) {
        free(norm_buf);
        return NULL;
    }

    int32_t lower_cap = norm_len * 2 + 32;
    UChar* lower_buf = (UChar*)malloc((size_t)lower_cap * sizeof(UChar));
    if (!lower_buf) {
        ucasemap_close(csm);
        free(norm_buf);
        return NULL;
    }

    int32_t lower_len = ucasemap_utf16ToLower(csm, lower_buf, lower_cap, norm_buf, norm_len, &status);

    if (status == U_BUFFER_OVERFLOW_ERROR) {
        status = U_ZERO_ERROR;
        lower_cap = lower_len + 16;
        UChar* temp = (UChar*)realloc(lower_buf, (size_t)lower_cap * sizeof(UChar));
        if (!temp) {
            free(lower_buf);
            ucasemap_close(csm);
            free(norm_buf);
            return NULL;
        }
        lower_buf = temp;
        lower_len = ucasemap_utf16ToLower(csm, lower_buf, lower_cap, norm_buf, norm_len, &status);
    }

    ucasemap_close(csm);
    free(norm_buf);

    if (U_FAILURE(status)) {
        free(lower_buf);
        return NULL;
    }

    int32_t out_cap = lower_len * 4 + 32;
    char* out = (char*)malloc((size_t)out_cap);
    if (!out) {
        free(lower_buf);
        return NULL;
    }

    int32_t out_len = 0;
    u_strToUTF8(out, out_cap, &out_len, lower_buf, lower_len, &status);

    if (status == U_BUFFER_OVERFLOW_ERROR) {
        status = U_ZERO_ERROR;
        out_cap = out_len + 16;
        char* temp = (char*)realloc(out, (size_t)out_cap);
        if (!temp) {
            free(out);
            free(lower_buf);
            return NULL;
        }
        out = temp;
        u_strToUTF8(out, out_cap, &out_len, lower_buf, lower_len, &status);
    }

    free(lower_buf);

    if (U_FAILURE(status)) {
        free(out);
        return NULL;
    }

    if (out_len >= 0 && out_len < out_cap) {
        out[out_len] = '\0';
    } else if (out_cap > 0) {
        out[out_cap - 1] = '\0';
    }

    return out;
}
