typedef struct {
    char* text;
    char* links;
} clean_result_t;

static int is_tag_char(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '/' || c == '!' || c == '-' || c == ':' || c == '_';
}

static const char* decode_entity(const char* s, size_t n, char* out, size_t* out_len) {
    if (n >= 5 && strncmp(s, "&amp;", 5) == 0) {
        out[0] = '&';
        *out_len = 1;
        return s + 5;
    }
    if (n >= 4 && strncmp(s, "&lt;", 4) == 0) {
        out[0] = '<';
        *out_len = 1;
        return s + 4;
    }
    if (n >= 4 && strncmp(s, "&gt;", 4) == 0) {
        out[0] = '>';
        *out_len = 1;
        return s + 4;
    }
    if (n >= 6 && strncmp(s, "&quot;", 6) == 0) {
        out[0] = '"';
        *out_len = 1;
        return s + 6;
    }
    if (n >= 6 && strncmp(s, "&apos;", 6) == 0) {
        out[0] = '\'';
        *out_len = 1;
        return s + 6;
    }
    if (n >= 6 && strncmp(s, "&nbsp;", 6) == 0) {
        out[0] = ' ';
        *out_len = 1;
        return s + 6;
    }
    out[0] = '&';
    *out_len = 1;
    return s + 1;
}

static void append_char(char** buf, size_t* len, size_t* cap, char c) {
    if (*len + 2 >= *cap) {
        size_t new_cap = (*cap == 0) ? 1024 : (*cap * 2);
        if (new_cap <= *cap) return;
        char* new_buf = (char*)realloc(*buf, new_cap);
        if (!new_buf) return;
        *buf = new_buf;
        *cap = new_cap;
    }
    (*buf)[(*len)++] = c;
    (*buf)[*len] = '\0';
}

static void append_str(char** buf, size_t* len, size_t* cap, const char* s, size_t n) {
    for (size_t i = 0; i < n; i++) {
        append_char(buf, len, cap, s[i]);
    }
}

static void extract_attr_value(const char* tag_start, const char* end, const char* attr, char** links, size_t* llen, size_t* lcap) {
    if (!tag_start || !end || !attr || !links) return;

    size_t attr_len = strlen(attr);
    const char* p = tag_start;

    while (p < end) {
        while (p < end && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) p++;
        if (p >= end) return;

        if (strncmp(p, attr, attr_len) == 0) {
            p += attr_len;
            while (p < end && (*p == ' ' || *p == '\t')) p++;
            if (p >= end || *p != '=') continue;
            p++;
            while (p < end && (*p == ' ' || *p == '\t')) p++;
            if (p >= end) return;

            char quote = *p;
            if (quote != '"' && quote != '\'') return;
            p++;

            const char* q = p;
            while (q < end && *q != quote) q++;
            if (q <= p) return;

            append_str(links, llen, lcap, p, (size_t)(q - p));
            append_char(links, llen, lcap, '\n');
            return;
        }

        while (p < end && *p != ' ' && *p != '\t' && *p != '\n' && *p != '\r' && *p != '>') p++;
    }
}

clean_result_t html_clean(const char* html) {
    clean_result_t r;
    r.text = NULL;
    r.links = NULL;

    if (!html) {
        r.text = strdup("");
        r.links = strdup("");
        return r;
    }

    size_t tlen = 0, tcap = 0, llen = 0, lcap = 0;
    const char* p = html;
    const size_t n = strlen(html);

    enum { TEXT, TAG, SCRIPT, STYLE } state = TEXT;
    int tag_depth = 0;
    const char* tag_start = NULL;

    for (size_t i = 0; i < n; i++) {
        char c = p[i];

        if (state == TEXT) {
            if (c == '<') {
                if (i + 7 < n && (strncmp(p + i, "<script", 7) == 0 || strncmp(p + i, "<SCRIPT", 7) == 0)) {
                    state = SCRIPT;
                    continue;
                }
                if (i + 6 < n && (strncmp(p + i, "<style", 6) == 0 || strncmp(p + i, "<STYLE", 6) == 0)) {
                    state = STYLE;
                    continue;
                }
                state = TAG;
                tag_depth = 1;
                tag_start = p + i + 1;
                continue;
            }
            if (c == '&') {
                char decoded[16];
                size_t dec_len = 0;
                const char* next = decode_entity(p + i, n - i, decoded, &dec_len);
                for (size_t j = 0; j < dec_len; j++) {
                    append_char(&r.text, &tlen, &tcap, decoded[j]);
                }
                i += (next - (p + i)) - 1;
                continue;
            }
            append_char(&r.text, &tlen, &tcap, c);
        } else if (state == TAG) {
            if (c == '<') {
                tag_depth++;
            } else if (c == '>') {
                tag_depth--;
                if (tag_depth <= 0) {
                    if (tag_start && (p + i) > tag_start) {
                        extract_attr_value(tag_start, p + i, "href", &r.links, &llen, &lcap);
                        extract_attr_value(tag_start, p + i, "src", &r.links, &llen, &lcap);
                    }
                    state = TEXT;
                    tag_start = NULL;
                }
            }
        } else if (state == SCRIPT) {
            if (c == '<' && i + 9 <= n && (strncmp(p + i, "</script>", 9) == 0 || strncmp(p + i, "</SCRIPT>", 9) == 0)) {
                state = TAG;
                tag_depth = 1;
                i += 8;
            }
        } else if (state == STYLE) {
            if (c == '<' && i + 8 <= n && (strncmp(p + i, "</style>", 8) == 0 || strncmp(p + i, "</STYLE>", 8) == 0)) {
                state = TAG;
                tag_depth = 1;
                i += 7;
            }
        }
    }

    if (!r.text) r.text = strdup("");
    if (!r.links) r.links = strdup("");

    return r;
}

void html_clean_free(clean_result_t r) {
    free(r.text);
    free(r.links);
